// === Tab: mySketch ===
const GRAVITY = {x:0.6, y:-0.2},
	FRICTION = 0.96,
	PARTICLE_RADIUS = 32;

var particles = [],
	emmiters = [],
	spliceIndices = [];

function preload() {
	particleImg=loadImage("https://openprocessing.org/sketch/1246349/files/texture (1).png");
}

function setup() {
	createCanvas(600, 600);

	for (let i = 0; i < 1; i++) {
		emmiters.push(new Emmiter(
			createVector(300, 500),
			1,
		));
	}
}

function draw() {
	background(0);
	GRAVITY.x=map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -0.3, 0.3);

	for (let p of particles) {
		p.update();
		p.render();
	}
	for (let e of emmiters) {
		e.update();
	}
	for (let i of spliceIndices) {
		particles.splice(i, 1);
	}
	spliceIndices = [];

}

// === Tab: tab2 ===
class Particle {
	constructor(pos, vel) {
		this.pos = pos;
		this.vel = vel;
		this.timeAlive = 0;
		this.col = color(
			random(random(230, 250), 255), 
			random(random(140, 180), 220), 
			random(random(60, 100), 120), 
			255);
	}
	update() {
		if ((this.pos.x != constrain(this.pos.x, -PARTICLE_RADIUS, width+PARTICLE_RADIUS) ||
			this.pos.y != constrain(this.pos.y, -PARTICLE_RADIUS, height+PARTICLE_RADIUS))||this.timeAlive>255) {
			spliceIndices.push(particles.indexOf(this));
		}
		this.vel.x+=GRAVITY.x;
		this.vel.y+=GRAVITY.y;
		this.vel.mult(FRICTION);
		this.pos.add(this.vel);
		this.pos.x = round(this.pos.x);
		this.pos.y = round(this.pos.y);
		this.timeAlive+=4;
		if (random()<0.05) {
			this.vel.add(p5.Vector.random2D());
		}
	}
	render() {
		this.col.setGreen(green(this.col)-(this.timeAlive*0.03));
		this.col.setAlpha(255-this.timeAlive);
		tint(this.col);
		image(particleImg, this.pos.x-PARTICLE_RADIUS, this.pos.y-PARTICLE_RADIUS, PARTICLE_RADIUS*2, PARTICLE_RADIUS*2);
	}
}

// === Tab: tab3 ===
class Emmiter {
	constructor(pos, speed) {
		this.pos = pos;
		this.speed = speed;
	}
	update() {
		if (frameCount%round(1/this.speed)===0) {
			particles.push(new Particle(
				this.pos.copy(),
				p5.Vector.fromAngle(random(TAU), random(4)),
			));
			particles.push(new Particle(
				this.pos.copy(),
				p5.Vector.fromAngle(random(TAU), random(4)),
			));
			particles.push(new Particle(
				this.pos.copy(),
				p5.Vector.fromAngle(random(TAU), random(4)),
			));
		}
	}
}

